/**
 * The lean Vitest dataset (`test` preset): a short deterministic window, one main card, a small
 * merchant pool — generated by `vitest.globalSetup` so the suite never copies personal data.
 * The hosted demo has its own generator (`v2/`, docs/demo-generator-plan.md).
 *
 * All money flows originate from one checking account plus the configured credit cards —
 * the same "master moves" model the reconciliation engine expects — so every derived
 * surface (deposits matching, billing months, gastos categories, net-worth buckets) is
 * internally consistent by construction.
 *
 * It ends at the CURRENT calendar month so current-month/rollover code paths always have data;
 * the seed keeps the history deterministic for a given month.
 */
import { monthKeyFromYmd } from "../calendarMonth.js";
import { chileCalendarTodayYmd } from "../chileDate.js";

/** `YYYY-MM`. */
export type DemoMonth = string;

export type DemoPreset = "test";

export type DemoChapterId = "test_baseline";

/** A recurring checking bill (rent, luz, internet, dividendo, …) with its gastos category. */
export type DemoBill = {
  /** Cartola description — also the merchant key the seeded category rule matches on. */
  desc: string;
  meanClp: number;
  /** `cc_expense_categories` slug (bills / others / real_estate_amortization / …). */
  categorySlug: string;
  day: number;
  /** Bill fires on calendar months divisible by this (contribuciones = 3). Default 1. */
  everyNMonths?: number;
};

export type DemoChapter = {
  id: DemoChapterId;
  /** Inclusive start month. Chapter runs until the next chapter's start. */
  from: DemoMonth;
  /** Net monthly salary landing in checking (CLP). Grows by `salaryAnnualGrowth`. */
  salaryClp: number;
  salaryAnnualGrowth: number;
  /** Itemized fixed outflows from checking — one movement per bill, categorized. */
  bills: DemoBill[];
  /** Mean discretionary CC spend per month across all cards. */
  ccSpendMeanClp: number;
  /** Weight multipliers per gastos category for this chapter (supermarket, fun, …). */
  categoryWeights?: Record<string, number>;
};

export type DemoEventKind =
  | "moving_costs"
  | "vacation_small"
  | "vacation_medium"
  | "vacation_big"
  | "house_down_payment"
  | "bonus";

export type DemoEvent = {
  month: DemoMonth;
  kind: DemoEventKind;
  /** Positive = extra spend (CC unless `viaChecking`), negative = extra income. */
  amountClp: number;
  viaChecking?: boolean;
  /** Big purchases can bill as N cuotas on the card (exercises installment views). */
  cuotas?: number;
  label: string;
  /** last4 of the card the event bills on (defaults to the first active card). */
  cardLast4?: string;
};

/** Scripted portfolio moves — buys are CLP from checking, sells a fraction of holdings. */
export type DemoTrade = {
  month: DemoMonth;
  asset: "stocks" | "crypto";
  action: "buy" | "sell";
  /** CLP amount for buys. */
  amountClp?: number;
  /** Fraction of current value for sells (0–1). */
  fraction?: number;
  /** Stock trades target one ticker (defaults to the first configured position). */
  ticker?: string;
};

export type DemoCard = {
  last4: string;
  cardGroup: "santander" | "bci";
  displayName: string;
  /** First month the card exists (statements start here). */
  from: DemoMonth;
  /** Relative share of the chapter's discretionary spend once active. */
  spendShare: number;
  /** Extra category weight multipliers stacked on the chapter's (per-card flavor). */
  merchantBias?: Record<string, number>;
  /** Monthly international USD purchases (adds a USD statement per month). */
  usdMonthly?: { meanUsd: number };
};

export type DemoNarrative = {
  preset: DemoPreset;
  /** Deterministic PRNG seed — same seed + same month, same DB. */
  seed: number;
  firstMonth: DemoMonth;
  /** Always the current calendar month — the demo/test data never goes stale. */
  lastMonth: DemoMonth;
  /**
   * Extend the market price series (equity_daily / fx_daily / uf_daily) this many years before
   * `lastMonth`, independent of the portfolio window, so the watchlist 10Y column has an anchor.
   * Unset (lean test preset) = no extension; the series starts at `firstMonth`.
   */
  marketHistoryYears?: number;
  chapters: DemoChapter[];
  events: DemoEvent[];
  cards: DemoCard[];
  /** Investment accounts to create (AFP/property/fondo optional). */
  withAfp: boolean;
  withProperty: boolean;
  /**
   * Mutual-fund account (fund_series_key + cuotas). The lean preset keeps one for
   * fund-valuation bucket coverage in Vitest; the demo preset invests through the
   * long-term ETFs instead.
   */
  withFondo: boolean;
  /**
   * Stock portfolio: monthly buys redirect a share of the sweep from `from` on, split
   * across positions by weight; the rest of the sweep (after the reserva slice) buys the
   * low-risk `longTermPositions` core. Tickers get `brokerage_acciones__<ticker>` /
   * `brokerage_long_term__<ticker>` leaves and need synthetic price anchors in the writers.
   */
  stocks: {
    from: DemoMonth;
    sweepShare: number;
    positions: { ticker: string; weight: number }[];
    longTermPositions: { ticker: string; weight: number }[];
  } | null;
  /** Crypto position (created only when `trades` buys into it). */
  withCrypto: boolean;
  /** Scripted buys/sells (rescates, take-profits, capitulations) for the "life" in the chart. */
  trades: DemoTrade[];
  /**
   * Leveraged house purchase: full property value + amortizing mortgage liability from
   * `month` on (down payment stays a separate viaChecking event). Without this, presets
   * with `withProperty` fall back to the bare down-payment valuation.
   */
  house: {
    month: DemoMonth;
    valueClp: number;
    mortgageClp: number;
    termMonths: number;
    monthlyRate: number;
  } | null;
};

function currentMonth(): DemoMonth {
  return monthKeyFromYmd(chileCalendarTodayYmd());
}

function monthsBack(n: number): DemoMonth {
  const cur = currentMonth();
  let y = Number(cur.slice(0, 4));
  let m = Number(cur.slice(5, 7)) - n;
  while (m <= 0) {
    m += 12;
    y -= 1;
  }
  return `${y}-${String(m).padStart(2, "0")}`;
}

/**
 * Lean Vitest narrative: ~18 months, one card, one cuota purchase (so installment-ledger
 * paths have rows), AFP + fondo for bucket coverage, no property. Deterministic for a
 * given calendar month.
 */
function testNarrative(): DemoNarrative {
  const first = monthsBack(17);
  return {
    preset: "test",
    seed: 424242,
    firstMonth: first,
    lastMonth: currentMonth(),
    chapters: [
      {
        id: "test_baseline",
        from: first,
        salaryClp: 1_500_000,
        salaryAnnualGrowth: 0.05,
        bills: [
          { desc: "PAGO ARRIENDO DEPTO TEST", meanClp: 320_000, categorySlug: "others", day: 5 },
          { desc: "ENEL CHILE", meanClp: 40_000, categorySlug: "bills", day: 12 },
          { desc: "VTR INTERNET", meanClp: 30_000, categorySlug: "bills", day: 15 },
          { desc: "PLAN CELULAR ENTEL", meanClp: 25_000, categorySlug: "bills", day: 10 },
        ],
        ccSpendMeanClp: 300_000,
      },
    ],
    events: [
      { month: monthsBack(9), kind: "vacation_medium", amountClp: 600_000, cuotas: 6, label: "Viaje test" },
      { month: monthsBack(3), kind: "vacation_small", amountClp: 200_000, label: "Escapada test" },
    ],
    cards: [
      {
        last4: "4321",
        cardGroup: "santander",
        displayName: "Tarjeta · Test Bank 4321",
        from: first,
        spendShare: 1,
        usdMonthly: { meanUsd: 80 },
      },
      {
        last4: "6605",
        cardGroup: "bci",
        displayName: "Tarjeta · Test Retail 6605",
        from: monthsBack(11),
        spendShare: 0.4,
      },
    ],
    withAfp: true,
    withProperty: false,
    withFondo: true,
    stocks: null,
    withCrypto: false,
    trades: [],
    house: null,
  };
}

export function demoNarrativeForPreset(preset: DemoPreset): DemoNarrative {
  if (preset !== "test") throw new Error(`unknown synthetic preset ${String(preset)}`);
  return testNarrative();
}

/** Chapter in effect for a month (chapters sorted by `from`; last one whose from ≤ month). */
export function chapterForMonth(narrative: DemoNarrative, month: DemoMonth): DemoChapter {
  const sorted = [...narrative.chapters].sort((a, b) => a.from.localeCompare(b.from));
  let current = sorted[0];
  if (!current) throw new Error("demo narrative needs at least one chapter");
  for (const ch of sorted) {
    if (ch.from <= month) current = ch;
  }
  return current;
}

/** Deterministic mulberry32 PRNG — same narrative seed ⇒ identical DB. */
export function demoRng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
